-- South Carolina multi-state / foreign LLC + flex/live-work research expansion.
on conflict (work_key) do update set question=excluded.question,required_evidence=excluded.required_evidence,priority=excluded.priority,next_action=excluded.next_action,owner_decision_required=excluded.owner_decision_required,metadata=excluded.metadata,updated_at=now();

on conflict (source_key) do update set work_key=excluded.work_key,source_title=excluded.source_title,source_url=excluded.source_url,status='ACTIVE',check_interval_minutes=excluded.check_interval_minutes,expected_signals=excluded.expected_signals,next_check_at=least(dd_research_sources.next_check_at,now()),metadata=excluded.metadata,updated_at=now();

on conflict (source_domain,source_key,review_type) do update set title=excluded.title,accounting_question=excluded.accounting_question,legal_or_tax_dependency=excluded.legal_or_tax_dependency,financial_statement_area=excluded.financial_statement_area,entity_scope=excluded.entity_scope,priority=excluded.priority,owner_decision_required=excluded.owner_decision_required,updated_at=now();
